1	"use client";
2	
3	import { useCallback, useEffect, useState } from "react";
4	import { AreaChart, MeterBar } from "@/components/ui/charts";
5	import { fmtBytes } from "@/components/ui/primitives";
6	
7	type Pt = { time: number; disk: number | null; maxdisk: number | null };
8	
9	const TIMEFRAMES = [
10	  { key: "day", label: "24h" },
11	  { key: "week", label: "7d" },
12	  { key: "month", label: "30d" },
13	] as const;
14	
15	const GB = 1024 ** 3;
16	
17	function xLabelsFor(rows: Pt[], tf: string): string[] {
18	  if (rows.length < 2) return [];
19	  const n = 6;
20	  const labels: string[] = [];
21	  for (let i = 0; i < n; i++) {
22	    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
23	    const d = new Date(rows[idx].time * 1000);
24	    labels.push(
25	      tf === "day"
26	        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
27	        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
28	    );
29	  }
30	  return labels;
31	}
32	
33	export function DiskUsageChart({
34	  serverId,
35	  planTotalGB,
36	  available = true,
37	}: {
38	  serverId: string;
39	  planTotalGB: number;
40	  available?: boolean;
41	}) {
42	  const [tf, setTf] = useState<string>("day");
43	  const [rows, setRows] = useState<Pt[] | null>(null);
44	  const [total, setTotal] = useState<number>(planTotalGB * GB);
45	  const [error, setError] = useState<string | null>(null);
46	
47	  const load = useCallback(
48	    async (timeframe: string, quiet: boolean) => {
49	      if (!quiet) setRows(null);
50	      setError(null);
51	      try {
52	        const res = await fetch(`/api/servers/${serverId}/disk?tf=${timeframe}`, {
53	          cache: "no-store",
54	        });
55	        if (!res.ok) throw new Error("unavailable");
56	        const json: { data?: Pt[]; planTotalBytes?: number } = await res.json();
57	        const data = (json.data ?? []).filter((r) => r && typeof r.time === "number");
58	        setRows(data);
59	        // Prefer the provisioned size reported by the hypervisor; fall back to
60	        // the plan's disk size when the guest doesn't report maxdisk.
61	        const maxFromRrd = Math.max(0, ...data.map((r) => r.maxdisk ?? 0));
62	        setTotal(maxFromRrd > 0 ? maxFromRrd : (json.planTotalBytes ?? planTotalGB * GB));
63	      } catch {
64	        setError("Disk metrics are temporarily unavailable — the hypervisor may be busy.");
65	        setRows([]);
66	      }
67	    },
68	    [serverId, planTotalGB]
69	  );
70	
71	  useEffect(() => {
72	    if (!available) return;
73	    void load(tf, false);
74	    const t = setInterval(() => void load(tf, true), 60_000);
75	    return () => clearInterval(t);
76	  }, [tf, load, available]);
77	
78	  if (!available) {
79	    return (
80	      <p className="text-sm text-slate-400">
81	        Disk usage appears once the server is provisioned and running.
82	      </p>
83	    );
84	  }
85	
86	  const loading = rows === null;
87	  const data = rows ?? [];
88	  const withUsage = data.filter((r) => typeof r.disk === "number" && (r.disk ?? 0) > 0);
89	  const hasUsage = withUsage.length > 0;
90	  const current = hasUsage ? (withUsage[withUsage.length - 1].disk ?? 0) : 0;
91	  const xLabels = xLabelsFor(data, tf);
92	  const totalGB = total / GB;
93	  const pct = total > 0 ? Math.min(100, (current / total) * 100) : 0;
94	
95	  return (
96	    <div className="space-y-5">
97	      <div className="flex items-center justify-between">
98	        <p className="section-label">Disk usage over time</p>
99	        <div className="flex gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
100	          {TIMEFRAMES.map((t) => (
101	            <button
102	              key={t.key}
103	              type="button"
104	              onClick={() => setTf(t.key)}
105	              className={`rounded-lg px-3 py-1 text-xs font-semibold transition-colors ${
106	                tf === t.key
107	                  ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white"
108	                  : "text-slate-400 hover:text-white"
109	              }`}
110	            >
111	              {t.label}
112	            </button>
113	          ))}
114	        </div>
115	      </div>
116	
117	      {/* Current usage meter */}
118	      <div>
119	        <div className="mb-1.5 flex justify-between text-sm">
120	          <span className="text-slate-400">Current</span>
121	          <span className="font-semibold">
122	            {hasUsage ? `${fmtBytes(current)} / ${fmtBytes(total)}` : `${totalGB.toFixed(0)} GB provisioned`}
123	          </span>
124	        </div>
125	        <MeterBar value={current} max={total || 1} />
126	        {hasUsage && (
127	          <p className="mt-1 text-xs text-slate-500">{pct.toFixed(1)}% used</p>
128	        )}
129	      </div>
130	
131	      {error && (
132	        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
133	          {error}
134	        </div>
135	      )}
136	
137	      {loading ? (
138	        <div className="skeleton h-52 w-full" />
139	      ) : !hasUsage ? (
140	        !error && (
141	          <p className="text-sm text-slate-500">
142	            The hypervisor isn&apos;t reporting in-guest disk usage for this VM yet, so only the
143	            provisioned size ({totalGB.toFixed(0)} GB) is shown. Historical usage appears here once
144	            the guest agent reports it.
145	          </p>
146	        )
147	      ) : (
148	        <AreaChart
149	          id={`disk-${tf}`}
150	          series={[
151	            {
152	              name: "Disk used",
153	              data: data.map((r) => (r.disk ?? 0) / GB),
154	              color: "#8a70fb",
155	            },
156	          ]}
157	          maxY={totalGB || undefined}
158	          yLabel={(v) => `${v.toFixed(0)} GB`}
159	          xLabels={xLabels}
160	        />
161	      )}
162	      <p className="text-xs text-slate-500">Refreshes automatically every 60 seconds.</p>
163	    </div>
164	  );
165	}
