133	// ---------------------------------------------------------------------------
134	// Live task progress (vzdump backup / qmrestore restore)
135	// ---------------------------------------------------------------------------
136	
137	/** Minimal shape any progress poller needs — satisfied by `pve` and `pveFor`. */
138	export type TaskClient = {
139	  get: (path: string, params?: Record<string, any>) => Promise<any>;
140	  node: string;
141	};
142	
143	export type TaskPhase = "backup" | "restore";
144	
145	/**
146	 * Parse the latest completion percentage and a human step out of Proxmox task
147	 * log lines. vzdump/qmrestore emit lines such as:
148	 *   "INFO:  42% (4.6 GiB of 11.0 GiB) in 12s, read: ..."
149	 *   "INFO: status: 42%"
150	 *   "progress 42% (read 4.6 GiB, ...)"
151	 *   "INFO: creating vzdump archive '/mnt/backup/...'"
152	 * Returns the last percentage seen (or null) plus a coarse step label.
153	 */
154	export function parseTaskProgress(
155	  lines: string[],
156	  phase: TaskPhase
157	): { pct: number | null; step: string | null } {
158	  let pct: number | null = null;
159	  let step: string | null = null;
160	  const verb = phase === "restore" ? "Restoring archive" : "Creating archive";
161	
162	  for (const raw of lines) {
163	    const line = String(raw ?? "");
164	    const m = line.match(/(\d{1,3})\s*%/);
165	    if (m) {
166	      const v = Number(m[1]);
167	      if (v >= 0 && v <= 100) pct = v;
168	    }
169	    const l = line.toLowerCase();
170	    if (l.includes("creating vzdump archive") || l.includes("starting new backup")) step = "Creating archive";
171	    else if (l.includes("restore") && (l.includes("start") || l.includes("archive"))) step = "Restoring archive";
172	    else if (l.includes("uploading") || l.includes("upload")) step = "Uploading to backup pool";
173	    else if (l.includes("transferred") || l.includes("read:")) step = verb;
174	    else if (l.includes("finished") || l.includes("finalize") || l.includes("closing")) step = "Finalizing";
175	  }
176	  if (pct !== null && step) step = `${step}… ${pct}%`;
177	  return { pct, step: step ?? (pct !== null ? `${verb}… ${pct}%` : null) };
178	}
179	
180	/**
181	 * Wait for a Proxmox task while streaming live progress. Polls `/status` (to
182	 * detect completion) and `/tasks/<upid>/log` (for the percentage) every ~2s and
183	 * invokes `onProgress(progress, step)` on each tick.
184	 *
185	 * Progress is monotonic and never regresses. The parsed task percentage (0..100)
186	 * is mapped into the caller's [base, base+span] window so multi-phase callers
187	 * (e.g. restore = stop→restore→start) can reserve sub-ranges. When no % has been
188	 * parsed yet, a coarse time-based creep keeps the bar moving up to a cap.
189	 */
190	export async function waitForTaskProgress(
191	  client: TaskClient,
192	  upid: string,
193	  onProgress: (progress: number, step: string) => void | Promise<void>,
194	  opts: { timeoutMs?: number; phase?: TaskPhase; base?: number; span?: number } = {}
195	): Promise<void> {
196	  const timeoutMs = opts.timeoutMs ?? 3_600_000;
197	  const phase = opts.phase ?? "backup";
198	  const base = opts.base ?? 0;
199	  const span = opts.span ?? 100;
200	  const enc = encodeURIComponent(upid);
201	
202	  const start = Date.now();
203	  let reported = base; // last value handed to onProgress (monotonic)
204	  let creep = 0; // coarse fallback estimate while no % is available
205	
206	  while (Date.now() - start < timeoutMs) {
207	    let stopped = false;
208	    let exitOk = true;
209	
210	    try {
211	      const status = await client.get(`/nodes/${client.node}/tasks/${enc}/status`);
212	      if (status?.status === "stopped") {
213	        stopped = true;
214	        exitOk = status.exitstatus === "OK";
215	      }
216	    } catch {
217	      /* transient — try again next tick */
218	    }
219	
220	    // Read the log tail and parse the newest percentage/step. Cheap enough for a
221	    // single VM backup; failures are non-fatal.
222	    let step: string | null = null;
223	    let pct: number | null = null;
224	    try {
225	      const log = await client.get(`/nodes/${client.node}/tasks/${enc}/log`, { start: 0, limit: 400 });
226	      const lines: string[] = Array.isArray(log) ? log.map((e: any) => e?.t ?? "") : [];
227	      const parsed = parseTaskProgress(lines, phase);
228	      pct = parsed.pct;
229	      step = parsed.step;
230	    } catch {
231	      /* ignore */
232	    }
233	
234	    // Compute the target within [base, base+span].
235	    let target: number;
236	    if (pct !== null) {
237	      target = base + (span * pct) / 100;
238	    } else {
239	      // Coarse creep: advance slowly toward 85% of the window until a % appears.
240	      creep = Math.min(creep + 4, 85);
241	      target = base + (span * creep) / 100;
242	    }
243	    if (target > reported) reported = target;
244	
245	    if (!stopped) {
246	      await onProgress(Math.round(Math.min(reported, base + span)), step ?? (phase === "restore" ? "Restoring…" : "Creating archive…"));
247	    }
248	
249	    if (stopped) {
250	      if (!exitOk) {
251	        // Surface the real failure reason from the log tail when available.
252	        throw new Error(`Proxmox task failed: ${upid}`);
253	      }
254	      return;
255	    }
256	
257	    await new Promise((r) => setTimeout(r, 2000));
258	  }
259	  throw new Error(`Proxmox task timed out: ${upid}`);
260	}
