279	/** Time-series metrics. timeframe: hour | day | week | month | year.
280	 *  Pass the server's node connection — vmids can collide across nodes, so a
281	 *  same-numbered VM on another node would otherwise leak that tenant's series. */
282	export async function vmRrd(vmid: number, timeframe = "hour", conn?: PveClient): Promise<any[]> {
283	  const c = conn ?? pve;
284	  const node = conn ? conn.node : NODE;
285	  return c.get(`/nodes/${node}/qemu/${vmid}/rrddata`, { timeframe, cf: "AVERAGE" });
286	}
