297	export async function listBackups(vmid?: number): Promise<any[]> {
298	  const content = await pve.get(`/nodes/${NODE}/storage/backup/content`, { content: "backup" });
299	  return vmid ? content.filter((b: any) => b.vmid === vmid) : content;
300	}
