302	/** Delete one backup archive by its Proxmox volume id. `client` = the node's pve client. */
303	export async function deleteBackup(client: any, volid: string): Promise<void> {
304	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
305	}
306	
307	/**
308	 * Retention: keep only the newest `keep` backups for a VM on the backup storage,
309	 * deleting the older ones (best-effort per file, oldest first). Runs after every
310	 * successful backup so customer servers never accumulate beyond their limit.
311	 * Returns how many were deleted.
312	 */
313	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
314	  const content: any[] = await client.get(`/nodes/${client.node}/storage/backup/content`, { content: "backup" });
315	  const mine = content
316	    .filter((b) => b.vmid === vmid && typeof b.volid === "string")
317	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
318	  const toDelete = mine.slice(Math.max(0, keep));
319	  let deleted = 0;
320	  for (const b of toDelete) {
321	    try {
322	      await deleteBackup(client, b.volid);
323	      deleted++;
324	    } catch (e) {
325	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
326	    }
327	  }
328	  return deleted;
329	}
330	
331	export async function storageStatus(storage: string): Promise<any> {
332	  return pve.get(`/nodes/${NODE}/storage/${storage}/status`);
333	}
