355	async function remove(job: Job) {
356	  const server = await loadServer(job);
357	  const { conn } = await nodeFor(server);
358	  if (!SANDBOX && server.vmid) {
359	    try {
360	      await destroyVm(conn, server.vmid);
361	    } catch (e: any) {
362	      // VM may never have been created; only swallow "does not exist"
363	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
364	    }
365	    // Best-effort: remove the per-server cloud-init snippet
366	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
367	  }
368	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
369	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
370	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
371	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
372	  // diskName and keep billing forever. Remove them and notify the owner. (The
373	  // reinstall guard already blocks the accidental case; a full server delete is an
374	  // intentional teardown, so we drop the volumes with it.)
375	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
376	  if (orphanVolumes.length > 0) {
377	    await db.volume.deleteMany({ where: { serverId: server.id } });
378	    for (const v of orphanVolumes) {
379	      await notify(
380	        v.userId,
381	        `Volume "${v.name}" was removed`,
382	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
383	        "/dashboard/volumes",
384	      ).catch(() => {});
385	    }
386	  }
387	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
388	  // server.delete cascade removes THIS running Job row — the success-path
389	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
390	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
391	  await db.server.delete({ where: { id: server.id } });
392	  if (!SANDBOX) await syncPortForwards();
393	}
