413	async function suspend(job: Job, unsuspend: boolean) {
414	  const server = await loadServer(job);
415	  if (SANDBOX) {
416	    if (unsuspend) {
417	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null } });
418	    } else {
419	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
420	    }
421	    return;
422	  }
423	  const { conn, row: nodeRow } = await nodeFor(server);
424	  if (unsuspend) {
425	    // The dedicated IP was returned to the pool while suspended — re-allocate one
426	    // and reconfigure the public network before starting the VM back up.
427	    if (server.vmid) {
428	      const { getSettingBool: _sb } = await import("../lib/settings");
429	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
430	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
431	      let reconfigured = alreadyHas ? true : false;
432	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
433	        try {
434	          const d = await allocateDedicatedIp(server.id, server.vmid);
435	          if (d) {
436	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
437	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
438	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
439	            });
440	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
441	            reconfigured = true;
442	          }
443	        } catch (e) {
444	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
445	        }
446	      }
447	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
448	      // the Virtual MAC + failover IP that suspend released back to the pool — that
449	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
450	      // with a valid, non-conflicting network instead of a dead public config.
451	      if (!reconfigured) {
452	        try {
453	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
454	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
455	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
456	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
457	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
458	          });
459	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
460	        } catch (e) {
461	          console.error("[worker] NAT fallback on unsuspend failed", e);
462	        }
463	      }
464	    }
465	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
466	    if (!SANDBOX) await syncPortForwards();
467	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
468	    await conn.waitForTask(upid);
469	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
470	  } else {
471	    try {
472	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
473	      await conn.waitForTask(upid);
474	    } catch { /* may already be stopped */ }
475	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
476	    if (!SANDBOX) await syncPortForwards();
477	    // Return the dedicated IP to the pool while the server is suspended, so it
478	    // can be handed to a paying server. Re-allocated on unsuspend.
479	    if (ovhConfigured()) {
480	      try {
481	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
482	        if (had) {
483	          await releaseDedicatedIp(server.id);
484	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
485	          // so leaving the released IP here makes the next server that claims it fail
486	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
487	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
488	          await db.server.update({
489	            where: { id: server.id },
490	            data: { ipAddress: null, ipv6: null },
491	          });
492	        }
493	      } catch (e) {
494	        console.error("[worker] release dedicated IP on suspend failed", e);
495	      }
496	    }
497	  }
498	}
