750	/**
751	 * Reverse a money side-effect that a job committed up-front but never delivered.
752	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
753	 * UI reflects the change immediately); if the job then fails terminally the money
754	 * must be unwound or the customer is charged for a resize that never happened
755	 * (up) or keeps a downgrade credit for hardware they still have (down).
756	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
757	 * double-reverse.
758	 */
759	async function reconcileFailedJob(job: Job) {
760	  if (job.type !== "RESIZE") return;
761	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
762	  const cents = p.prorateCents ?? 0;
763	  if (cents <= 0 || !job.serverId) return;
764	
765	  // Idempotency: skip if we already reversed this exact job.
766	  const already = await db.auditLog.findFirst({
767	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
768	  });
769	  if (already) return;
770	
771	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
772	  if (!server) return;
773	
774	  try {
775	    if (p.direction === "up") {
776	      // Upgrade charge never delivered → refund the prorated charge.
777	      await db.$transaction([
778	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
779	        db.walletTransaction.create({
780	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
781	        }),
782	      ]);
783	    } else if (p.direction === "down") {
784	      // Downgrade credit was given but hardware unchanged → claw the credit back.
785	      // Guarded so it can never drive the balance negative; if the customer already
786	      // spent it, we log and leave it (best-effort — they keep a small windfall).
787	      await db.$transaction(async (tx) => {
788	        await debitWallet(tx, server.userId, cents);
789	        await tx.walletTransaction.create({
790	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
791	        });
792	      });
793	    }
794	    await db.auditLog.create({
795	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
796	    });
797	  } catch (e: any) {
798	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
799	    await db.auditLog.create({
800	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
801	    }).catch(() => {});
802	  }
803	}
