805	async function runJob(job: Job) {
806	  // The job is already atomically claimed (status RUNNING, attempts incremented)
807	  // by the loop's compare-and-swap before we get here — see the CAS in main().
808	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
809	  try {
810	    await handlers[job.type](job);
811	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
812	    console.log(`[worker] job ${job.id} DONE`);
813	  } catch (e: any) {
814	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
815	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
816	    // leak the server's root password into the thrown message. Redact it before
817	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
818	    // sever the match. Best-effort — never let redaction lookup fail the job path.
819	    if (job.serverId) {
820	      try {
821	        const s = await db.server.findUnique({
822	          where: { id: job.serverId },
823	          select: { rootPassword: true, rootPasswordEnc: true },
824	        });
825	        const pw = s ? serverRootPassword(s) : null;
826	        if (pw) error = error.split(pw).join("***");
827	      } catch {
828	        /* best-effort redaction */
829	      }
830	    }
831	    error = error.slice(0, 2000);
832	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
833	    const current = await db.job.findUnique({ where: { id: job.id } });
834	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
835	    await db.job.update({
836	      where: { id: job.id },
