import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { getGuestDiskUsage, pve, node as defaultNode, pveFor } from "@/lib/proxmox";

export const dynamic = "force-dynamic";

type Pt = { time: number; disk: number | null; maxdisk: number | null };

// Chart timeframe → lookback window (ms). Matches DiskUsageChart's 24h/7d/30d.
const WINDOW_MS: Record<string, number> = {
  day: 24 * 60 * 60_000,
  week: 7 * 24 * 60 * 60_000,
  month: 30 * 24 * 60 * 60_000,
};

/**
 * Real in-guest disk usage for a server the current user owns.
 *
 * Data comes from ServerDiskSample (collected by the worker via the QEMU guest
 * agent, since Proxmox RRD reports disk=0 for QEMU VMs) for the requested
 * window, plus a fresh live get-fsinfo reading appended as the current point.
 * Falls back to the latest stored sample when the live call isn't ready, and to
 * an empty series (chart shows the "not reporting" note) only when neither the
 * agent nor any sample yields anything.
 */
export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const tf = req.nextUrl.searchParams.get("tf") ?? "day";

  const server = await db.server.findUnique({
    where: { id },
    include: { node: true, plan: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const planTotalBytes = server.plan.diskGB * 1024 ** 3;
  const since = new Date(Date.now() - (WINDOW_MS[tf] ?? WINDOW_MS.day));

  // 1. Stored history for the window.
  let samples: { ts: Date; usedBytes: bigint; totalBytes: bigint }[] = [];
  try {
    samples = await db.serverDiskSample.findMany({
      where: { serverId: id, ts: { gte: since } },
      orderBy: { ts: "asc" },
      select: { ts: true, usedBytes: true, totalBytes: true },
    });
  } catch {
    samples = [];
  }

  const data: Pt[] = samples.map((s) => ({
    time: Math.floor(s.ts.getTime() / 1000),
    disk: Number(s.usedBytes),
    maxdisk: Number(s.totalBytes),
  }));

  // 2. Fresh live reading for the current point (best-effort).
  let current: { usedBytes: number; totalBytes: number } | null = null;
  try {
    const client = server.node
      ? pveFor({
          apiUrl: server.node.apiUrl,
          pveNode: server.node.pveNode,
          tokenId: server.node.tokenId,
          tokenSecret: server.node.tokenSecret,
        })
      : pve;
    const pnode = server.node?.pveNode ?? defaultNode;
    current = await getGuestDiskUsage(client, pnode, server.vmid, planTotalBytes);
  } catch {
    current = null;
  }

  // Fall back to the newest stored sample when the live call isn't ready.
  if (!current && samples.length > 0) {
    const last = samples[samples.length - 1];
    current = { usedBytes: Number(last.usedBytes), totalBytes: Number(last.totalBytes) };
  }

  // Append the current reading so the chart always shows the freshest value
  // (and isn't empty when there are no samples yet but the agent responds).
  if (current) {
    data.push({
      time: Math.floor(Date.now() / 1000),
      disk: current.usedBytes,
      maxdisk: current.totalBytes,
    });
  }

  // Prefer the fsinfo/sample total; fall back to the plan's provisioned size.
  const totalBytes =
    current?.totalBytes ??
    (samples.length > 0 ? Number(samples[samples.length - 1].totalBytes) : planTotalBytes);

  return NextResponse.json({ data, planTotalBytes: totalBytes });
}

